"use client";

import { useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { LandingView } from "@/components/LandingView";
import { DashboardView } from "@/components/DashboardView";

export default function Home() {
  const [isLanding, setIsLanding] = useState(true);

  return (
    <main className="w-full min-h-screen bg-[#050505] overflow-hidden">
      <AnimatePresence mode="wait">
        {isLanding ? (
          <motion.div key="landing" exit={{ opacity: 0, scale: 0.95 }} transition={{ duration: 0.5 }}>
            <LandingView onEnterAegis={() => setIsLanding(false)} />
          </motion.div>
        ) : (
          <DashboardView key="dashboard" />
        )}
      </AnimatePresence>
    </main>
  );
}
